MagickBooleanType WriteImages(const ImageInfo *image_info, Image *images,
                              const char *filename, ExceptionInfo *exception)
{
  Image
    *image;

  ImageInfo
    *clone_info;

  MagickBooleanType
    status;

  register ssize_t
    i;

  size_t
    scene;

  clone_info = CloneImageInfo(image_info);
  if (clone_info == (ImageInfo *) NULL)
    return(MagickFalse);
  status = MagickTrue;
  scene = 0;
  for (i=0; i < (ssize_t) GetImageListLength(images); i++)
  {
    image = GetImageList(images,i);
    if (image == (Image *) NULL)
      continue;
    if (i == 0)
    {
      (void) FormatMagickString(clone_info->filename,MaxTextLength,"%s",filename);
      (void) SetImageInfo(clone_info,image,exception);
      if (clone_info->adjoin != MagickFalse)
      {
        (void) SetImageScene(image,scene);
        (void) SetImageInfo(clone_info,image,exception);
        if (WriteImage(clone_info,image,exception) == MagickFalse)
          status = MagickFalse;
        scene++;
        continue;
      }
    }
    (void) SetImageScene(image,scene);
    (void) SetImageInfo(clone_info,image,exception);
    if (WriteImage(clone_info,image,exception) == MagickFalse)
      status = MagickFalse;
    scene++;
  }
  clone_info = DestroyImageInfo(clone_info);
  return(status);
}

MagickBooleanType WriteImages(const ImageInfo *image_info, Image *images,
                              const char *filename, ExceptionInfo *exception)
{
  Image
    *image;

  ImageInfo
    *write_info;

  MagickBooleanType
    status;

  register ssize_t
    i;

  size_t
    scene;

  assert(image_info != (ImageInfo *) NULL);
  assert(images != (Image *) NULL);
  assert(filename != (char *) NULL);
  assert(exception != (ExceptionInfo *) NULL);
  (void) memset(exception, 0, sizeof(*exception));

  if (image_info->adjoin != MagickFalse)
    {
      status=WriteImage(image_info, images, filename, exception);
      return(status);
    }

  write_info=CloneImageInfo(image_info);
  if (write_info == (ImageInfo *) NULL)
    return(MagickFalse);

  image=images;
  scene=0;
  status=MagickTrue;
  for (i=0; i < (ssize_t) GetImageListLength(images); i++)
  {
    char
      *unique_filename;

    unique_filename=GetUniqueFilename(write_info, filename, scene, exception);
    if (unique_filename == (char *) NULL)
      {
        status=MagickFalse;
        break;
      }

    write_info->filename=unique_filename;
    (void) CloneImageInfo(write_info);
    write_info->scene=scene;
    status=WriteImage(write_info, image, unique_filename, exception);
    scene++;
    image=image->next;
  }

  DestroyImageInfo(write_info);
  return(status);
}

MagickBooleanType WriteImages(const ImageInfo *image_info, Image *images,
                              const char *filename, ExceptionInfo *exception)
{
  Image
    *image;

  ImageInfo
    *clone_info;

  MagickBooleanType
    status;

  assert(image_info != (const ImageInfo *) NULL);
  assert(images != (Image *) NULL);
  assert(filename != (const char *) NULL);
  assert(exception != (ExceptionInfo *) NULL);

  clone_info = CloneImageInfo(image_info);
  if (clone_info == (ImageInfo *) NULL)
    return MagickFalse;

  GetPathComponent(clone_info->filename, TailPath, clone_info->filename);
  SetImageInfo(clone_info, images, exception);
  if (clone_info->adjoin != MagickFalse)
  {
    StatusHandler status_handler;

    status_handler = (StatusHandler) SetMagickHandler(exception, (Handler) NULL,
                                                    MagickTrue);
    image = CloneImageList(images, exception);
    if (image != (Image *) NULL)
    {
      if (image->scene == 0)
        image->scene = 1;
      if (image->next != (Image *) NULL)
      {
        Image
          *next;

        next = image->next;
        while (next != (Image *) NULL)
        {
          next->scene = image->scene + 1;
          next = next->next;
        }
      }
    }
    SetMagickHandler(exception, status_handler, MagickFalse);
    status = WriteImages(clone_info, image, filename, exception);
    if (image != (Image *) NULL)
      DestroyImageList(image);
  }
  else
  {
    image = images;
    while (image != (Image *) NULL)
    {
      char
        *basename;

      basename = CopyMagickString(clone_info->filename, filename,
                                  MaxTextLength);
      if (image->scene != 0)
      {
        char
          number[MagickPathExtent];

        (void) FormatMagickString(number, MagickPathExtent, "%0*d", (int)
          clone_info->digits, image->scene);
        basename = ReplaceString(basename, "##", number);
      }
      status = WriteImage(clone_info, image, basename, exception);
      if (status == MagickFalse)
        break;
      image = GetNextImageInList(image);
    }
  }
  clone_info = DestroyImageInfo(clone_info);
  return status;
}

MagickBooleanType WriteImages(const ImageInfo *image_info, Image *images,
                              const char *filename, ExceptionInfo *exception)
{
  Image
    *image;

  ImageInfo
    *clone_info;

  MagickBooleanType
    status;

  register ssize_t
    i;

  size_t
    scene;

  clone_info = CloneImageInfo(image_info);
  if (clone_info == (ImageInfo *) NULL)
    return(MagickFalse);
  status = MagickTrue;
  scene = 0;
  for (i=0; i < (ssize_t) GetImageListLength(images); i++)
  {
    image = GetImageList(images,i);
    if (image == (Image *) NULL)
      continue;
    if (clone_info->adjoin != MagickFalse)
      {
        image->scene = scene;
        status = WriteImage(clone_info, image, exception);
        if (status == MagickFalse)
          break;
        scene++;
      }
    else
      {
        char
          *temp_filename;

        temp_filename = AcquireStringFormat("%s-%s", filename, image->filename);
        (void) FormatImageFilename(clone_info, image, temp_filename, exception);
        status = WriteImage(clone_info, image, exception);
        RelinquishMemory(temp_filename);
        if (status == MagickFalse)
          break;
      }
  }
  clone_info = DestroyImageInfo(clone_info);
  return(status);
}

MagickBooleanType WriteImages(const ImageInfo *image_info, Image *images,
                              const char *filename, ExceptionInfo *exception)
{
  Image
    *image;

  ImageInfo
    *clone_info;

  MagickBooleanType
    status;

  register ssize_t
    i;

  size_t
    scene;

  status = MagickTrue;
  clone_info = CloneImageInfo(image_info);
  if (clone_info == (ImageInfo *) NULL)
    return(MagickFalse);
  if (images->next == (Image *) NULL)
    clone_info->adjoin = MagickFalse;
  if (clone_info->adjoin != MagickFalse)
  {
    image = images;
    scene = 0;
    for (i=0; i < (ssize_t) GetImageListLength(images); i++)
    {
      char
        *unique_filename;

      unique_filename = (char *) NULL;
      if (clone_info->number_scenes != 0)
      {
        if ((image->scene < 1) || (image->scene > clone_info->number_scenes))
          continue;
      }
      if (image->scene != 0)
        unique_filename = GetImageFilename(clone_info, image->scene, filename);
      else
        unique_filename = (char *) AcquireString(filename);
      clone_info->filename = unique_filename;
      if (image->scene != 0)
        clone_info->scene = image->scene;
      else
        clone_info->scene = scene;
      status = WriteImage(clone_info, image, exception);
      if (status == MagickFalse)
        break;
      clone_info->scene++;
      image = GetNextImageInList(image);
      scene++;
    }
  }
  else
  {
    image = images;
    scene = 0;
    for (i=0; i < (ssize_t) GetImageListLength(images); i++)
    {
      char
        *unique_filename;

      unique_filename = (char *) NULL;
      if (image->scene != 0)
        unique_filename = GetImageFilename(clone_info, image->scene, filename);
      else
        unique_filename = (char *) AcquireString(filename);
      clone_info->filename = unique_filename;
      if (image->scene != 0)
        clone_info->scene = image->scene;
      else
        clone_info->scene = scene;
      status = WriteImage(clone_info, image, exception);
      if (status == MagickFalse)
        break;
      clone_info->scene++;
      image = GetNextImageInList(image);
      scene++;
    }
  }
  clone_info = DestroyImageInfo(clone_info);
  return(status);
}
